/**
 * ModelSelector Component Tests
 */

import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ModelSelector } from './ModelSelector';
import { OpenRouterModel } from '../types/capabilities';

describe('ModelSelector', () => {
  const mockModels: OpenRouterModel[] = [
    {
      id: 'openai/gpt-4',
      name: 'GPT-4',
      context_length: 8192,
      pricing: {
        prompt: '0.00003',
        completion: '0.00006'
      },
      architecture: {
        modality: 'text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    },
    {
      id: 'anthropic/claude-3-haiku',
      name: 'Claude 3 Haiku',
      context_length: 200000,
      pricing: {
        prompt: '0.00000025',
        completion: '0.00000125'
      },
      architecture: {
        modality: 'text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    },
    {
      id: 'google/gemini-pro',
      name: 'Gemini Pro',
      context_length: 32768,
      pricing: {
        prompt: '0.0000005',
        completion: '0.0000015'
      },
      architecture: {
        modality: 'text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    },
    {
      id: 'openrouter/mistral-7b',
      name: 'Mistral 7B',
      context_length: 32768,
      pricing: {
        prompt: '0.00000011',
        completion: '0.00000033'
      },
      architecture: {
        modality: 'text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    }
  ];

  it('should render without crashing', () => {
    const { container } = render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );
    expect(container).toBeTruthy();
  });

  it('should display the select dropdown', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    const button = screen.getByRole('button');
    expect(button).toBeTruthy();
  });

  it('should show placeholder when no model is selected', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    expect(screen.getByText('Select a model...')).toBeTruthy();
  });

  it('should call onSelectModel when a model is selected', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    const button = screen.getByRole('button');
    fireEvent.click(button);

    // Find and click the first model option
    const modelOption = screen.getByText('GPT-4');
    fireEvent.click(modelOption);

    expect(onSelectModel).toHaveBeenCalledWith('openai/gpt-4');
  });

  it('should display model name and ID correctly when selected', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={vi.fn()}
      />
    );

    expect(screen.getByText('GPT-4')).toBeTruthy();
    expect(screen.getByText('openai/gpt-4')).toBeTruthy();
  });

  it('should show pricing information per 1M tokens', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={vi.fn()}
      />
    );

    // Check for price badge
    expect(screen.getByText('$30.00/1M')).toBeTruthy();
  });

  it('should show context window length', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='anthropic/claude-3-haiku'
        onSelectModel={vi.fn()}
      />
    );

    expect(screen.getByText('200k ctx')).toBeTruthy();
  });

  it('should sort models by price (ascending)', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    const button = screen.getByRole('button');
    fireEvent.click(button);

    // Check that cheapest model (Mistral 7B) appears first
    const options = screen.getAllByText(/Mistral/i);
    expect(options.length).toBeGreaterThan(0);

    // In the dropdown, prices should be sorted ascending
    const prices = screen.getAllByRegExp(/[$<]\d+/);
    const firstPrice = prices[0].textContent;
    expect(firstPrice).toBe('<$0.44');
  });

  it('should be disabled when disabled prop is true', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
        disabled={true}
      />
    );

    const button = screen.getByRole('button');
    expect(button).toHaveAttribute('disabled');
  });

  it('should show "No models available" for empty arrays', () => {
    render(
      <ModelSelector
        models={[]}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    expect(screen.getByText('No models available')).toBeTruthy();
  });

  it('should show dropdown menu when clicking on the trigger', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    const trigger = screen.getByRole('button');
    expect(screen.queryByRole('menu')).toBeNull();

    fireEvent.click(trigger);

    expect(screen.getByText('Search models...')).toBeTruthy();
  });

  it('should show search results when typing', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Type in search
    const searchInput = screen.getByPlaceholderText('Search models...');
    fireEvent.change(searchInput, { target: { value: 'Mistral' } });

    expect(screen.getByText('Mistral 7B')).toBeTruthy();
  });

  it('should show "No models found" when search yields no results', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Type in search
    const searchInput = screen.getByPlaceholderText('Search models...');
    fireEvent.change(searchInput, { target: { value: 'Nonexistent Model' } });

    expect(screen.getByText('No models found')).toBeTruthy();
    expect(screen.getByText('Try a different search term')).toBeTruthy();
  });

  it('should show model count in search results', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Type in search
    const searchInput = screen.getByPlaceholderText('Search models...');
    fireEvent.change(searchInput, { target: { value: 'GPT' } });

    expect(screen.getByText('1 model found')).toBeTruthy();
  });

  it('should show model count for multiple results', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Type in search
    const searchInput = screen.getByPlaceholderText('Search models...');
    fireEvent.change(searchInput, { target: { value: 'a' } });

    expect(screen.getByText('3 models found')).toBeTruthy();
  });

  it('should close dropdown when clicking outside', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    const button = screen.getByRole('button');
    fireEvent.click(button);

    expect(screen.getByText('Search models...')).toBeTruthy();

    // Click outside
    fireEvent.mouseDown(document);

    await waitFor(() => {
      expect(screen.queryByText('Search models...')).toBeNull();
    });
  });

  it('should show clear button when model is selected', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={vi.fn()}
      />
    );

    expect(screen.getByText('✕')).toBeTruthy();
  });

  it('should clear selection when clear button is clicked', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={onSelectModel}
      />
    );

    const clearButton = screen.getByText('✕');
    fireEvent.click(clearButton);

    expect(onSelectModel).toHaveBeenCalledWith(null);
  });

  it('should display prompt and completion prices separately in dropdown', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Check that model shows both prompt and completion prices
    expect(screen.getByText('Prompt:')).toBeTruthy();
    expect(screen.getByText('Completion:')).toBeTruthy();
  });

  it('should show correct colors for different price tiers', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Check for free model (if any)
    // Check for cheap model (green)
    // Check for medium model (yellow)
    // Check for expensive model (orange/red)
  });

  it('should show footer with pricing note', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    expect(screen.getByText('Prices shown per 1M tokens')).toBeTruthy();
  });

  it('should handle zero pricing correctly', () => {
    const freeModel: OpenRouterModel = {
      id: 'free/model',
      name: 'Free Model',
      context_length: 1000,
      pricing: {
        prompt: '0',
        completion: '0'
      },
      architecture: {
        modality: 'text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    };

    render(
      <ModelSelector
        models={[freeModel]}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    expect(screen.getByText('Free')).toBeTruthy();
  });

  it('should show selected state in dropdown', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    const selectedOption = screen.getByText('GPT-4').closest('button');
    expect(selectedOption).toHaveClass('bg-cyan-500/10');
  });

  it('should show checkmark for selected option', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    expect(screen.getByText('✓')).toBeTruthy();
  });

  it('should allow unselecting by clicking the same model again', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId='openai/gpt-4'
        onSelectModel={onSelectModel}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Click the same model again
    fireEvent.click(screen.getByText('GPT-4'));

    expect(onSelectModel).toHaveBeenCalledWith(null);
  });

  it('should close dropdown when selecting a model', () => {
    const onSelectModel = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={onSelectModel}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    // Select a model
    fireEvent.click(screen.getByText('GPT-4'));

    expect(screen.queryByText('Search models...')).toBeNull();
  });

  it('should handle model with very small prices correctly', () => {
    const cheapModel: OpenRouterModel = {
      id: 'cheap/model',
      name: 'Cheap Model',
      context_length: 1000,
      pricing: {
        prompt: '0.00000001',
        completion: '0.00000001'
      },
      architecture: {
        modality: 'text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    };

    render(
      <ModelSelector
        models={[cheapModel]}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // Open dropdown
    fireEvent.click(screen.getByRole('button'));

    expect(screen.getByText('<$0.02')).toBeTruthy();
  });

  it('should handle model with large context length', () => {
    const largeContextModel: OpenRouterModel = {
      id: 'large/model',
      name: 'Large Context Model',
      context_length: 1000000,
      pricing: {
        prompt: '0.00001',
        completion: '0.00002'
      },
      architecture: {
