import { describe, it, expect, vi } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ModelSelector } from './ModelSelector';
import { OpenRouterModel } from '../types/capabilities';

describe('ModelSelector', () => {
  const mockModels: OpenRouterModel[] = [
    {
      id: 'openai/gpt-4o',
      name: 'GPT-4o',
      context_length: 128000,
      pricing: {
        prompt: '0.0025',
        completion: '0.01'
      },
      architecture: {
        modality: 'text->text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    },
    {
      id: 'anthropic/claude-sonnet-4-20250514',
      name: 'Claude Sonnet 4',
      context_length: 200000,
      pricing: {
        prompt: '0.003',
        completion: '0.015'
      },
      architecture: {
        modality: 'text->text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    },
    {
      id: 'google/gemini-2.5-flash-preview',
      name: 'Gemini 2.5 Flash',
      context_length: 1000000,
      pricing: {
        prompt: '0.0001',
        completion: '0.0004'
      },
      architecture: {
        modality: 'text->text',
        input_modalities: ['text', 'image'],
        output_modalities: ['text']
      }
    },
    {
      id: 'free/model',
      name: 'Free Model',
      context_length: 4000,
      pricing: {
        prompt: '0',
        completion: '0'
      },
      architecture: {
        modality: 'text->text',
        input_modalities: ['text'],
        output_modalities: ['text']
      }
    }
  ];

  it('should render without crashing', () => {
    const { container } = render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );
    expect(container).toBeTruthy();
  });

  it('should display select dropdown', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    const select = screen.getByRole('combobox');
    expect(select).toBeTruthy();
  });

  it('should show placeholder when no model selected', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
        placeholder="Select a model..."
      />
    );

    const select = screen.getByRole('combobox');
    expect(select).toHaveValue('');
  });

  it('should call onSelectModel when selection changes', () => {
    const handleSelect = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={handleSelect}
      />
    );

    const select = screen.getByRole('combobox');
    fireEvent.change(select, { target: { value: 'openai/gpt-4o' } });

    expect(handleSelect).toHaveBeenCalledWith('openai/gpt-4o');
  });

  it('should display model name and ID correctly', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={'openai/gpt-4o'}
        onSelectModel={vi.fn()}
      />
    );

    const select = screen.getByRole('combobox');
    expect(select).toHaveValue('openai/gpt-4o');
  });

  it('should show pricing information per 1M tokens', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // GPT-4o: $2.50 + $10.00 = $12.50 per 1M
    const gpt4oOption = screen.getByText(/GPT-4o.*\$2\.50.*\$10\.00/);
    expect(gpt4oOption).toBeTruthy();
  });

  it('should show context window length', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    // Should show "128k ctx" for GPT-4o
    const ctxInfo = screen.getByText(/128k ctx/);
    expect(ctxInfo).toBeTruthy();
  });

  it('should show Free for free models', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    const freeOption = screen.getByText(/Free Model.*Free/);
    expect(freeOption).toBeTruthy();
  });

  it('should sort models by total price (ascending)', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    const select = screen.getByRole('combobox');
    const options = Array.from(select.querySelectorAll('option'));

    // First should be Free Model ($0)
    expect(options[0].textContent).toContain('Free Model');

    // Last should be Claude Sonnet 4 ($18 per 1M)
    expect(options[options.length - 1].textContent).toContain('Claude Sonnet 4');
  });

  it('should respect disabled prop', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
        disabled={true}
      />
    );

    const select = screen.getByRole('combobox');
    expect(select).toBeDisabled();
  });

  it('should show "No models available" for empty arrays', () => {
    render(
      <ModelSelector
        models={[]}
        selectedModelId={null}
        onSelectModel={vi.fn()}
      />
    );

    const noModelsMsg = screen.getByText('No models available');
    expect(noModelsMsg).toBeTruthy();
  });

  it('should handle custom placeholder', () => {
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={null}
        onSelectModel={vi.fn()}
        placeholder="Choose your model..."
      />
    );

    const select = screen.getByRole('combobox');
    expect(select).toHaveValue('');
  });

  it('should handle clearing selection with null', () => {
    const handleSelect = vi.fn();
    render(
      <ModelSelector
        models={mockModels}
        selectedModelId={'openai/gpt-4o'}
        onSelectModel={handleSelect}
      />
    );

    const select = screen.getByRole('combobox');
    expect(select).toHaveValue('openai/gpt-4o');
  });
});

